-- Ficha de Primitivo Santos y su Orquesta.
--
-- La biografía de relleno eran dos frases sin un solo hecho verificable. instruments: se
-- añade bandoneon (ya tocaba piano) — tocó ambos en un hotel de Washington antes de que
-- despegara la orquesta. Un premio registrado: la condecoración de 2011 (Orden del Mérito de
-- Duarte, Sánchez y Mella / "Padres de la Patria"), por decreto de Leonel Fernández. Camboy
-- Estévez, Rafaelito Cruz, Héctor Zarzuela, Ite Jerez, Ray Martínez, Marino Solano, Juan
-- Colón, Carmen Luisa, Willie Contreras y Joa Aguilera no tienen ficha: ver
-- ARTISTAS_FALTANTES.md y MUSICOS_PENDIENTES.md.

UPDATE artists SET instruments = ARRAY['piano', 'bandoneon']::text[] WHERE slug = 'primitivo-santos-y-su-orquesta';

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 2011, 'Condecoración de los Padres de la Patria, con pensión especial por decreto del presidente Leonel Fernández', true, 'Hoy Digital (22 nov 2011); Zona Cero (6 jun 2018); gentequehacenlahistoria.blogspot.com'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'primitivo-santos-y-su-orquesta' AND a.name = 'Gobierno de la República Dominicana' AND cat.name = 'Orden del Mérito de Duarte, Sánchez y Mella'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 2011);

